dict.string:
q=$1
state="${alfred_workflow_data:-$HOME/Library/Caches/caffeinate-alfred}/end"
item() { printf '{"title":"%s","subtitle":"%s","arg":"%s","valid":%s}' "$1" "$2" "$3" "${4:-true}"; }

if pgrep -qf '^/usr/bin/caffeinate -is( -t [0-9]+)?$'; then
  end=$(cat "$state" 2>/dev/null)
  if [ -n "$end" ]; then status="Caffeinate is ON until $(date -r "$end" +%H:%M)"; else status="Caffeinate is ON (no timeout)"; fi
  [ -z "$q" ] && { printf '{"items":[%s]}' "$(item "$status" "Enter to turn off" off)"; exit; }
else
  status="Caffeinate is OFF"
  [ -z "$q" ] && { printf '{"items":[%s]}' "$(item "$status" "Enter to keep awake with no timeout, or type a duration: 30, 90m, 2h" on:0)"; exit; }
fi

case $q in
  *[0-9]h) secs=$(( ${q%h} * 3600 )) ;;
  *[0-9]m) secs=$(( ${q%m} * 60 )) ;;
  *[0-9]s) secs=${q%s} ;;
  *[0-9]) secs=$(( q * 60 )) ;;
esac
case ${q%[hms]} in ''|*[!0-9]*) secs= ;; esac
if [ -z "$secs" ] || [ "$secs" -eq 0 ]; then
  printf '{"items":[%s]}' "$(item "Not a duration: $q" "Use minutes or a unit: 30, 90m, 2h, 45s" "" false)"; exit
fi
until=$(date -r $(( $(date +%s) + secs )) +%H:%M)
printf '{"items":[%s]}' "$(item "Keep awake until $until" "$status · caffeinate -is -t $secs" "on:$secs")"

dir="${alfred_workflow_data:-$HOME/Library/Caches/caffeinate-alfred}"
pkill -f '^/usr/bin/caffeinate -is( -t [0-9]+)?$'
rm -f "$dir/end"
case $1 in
  on:0) nohup /usr/bin/caffeinate -is >/dev/null 2>&1 &
        echo "Caffeinate ON (no timeout)" ;;
  on:*) secs=${1#on:}
        nohup /usr/bin/caffeinate -is -t "$secs" >/dev/null 2>&1 &
        mkdir -p "$dir" && echo $(( $(date +%s) + secs )) > "$dir/end"
        echo "Caffeinate ON until $(date -r $(( $(date +%s) + secs )) +%H:%M)" ;;
  *) echo "Caffeinate OFF" ;;
esac
